package com.jobs.im

import java.time.Instant
import org.json.JSONObject

data class ReceiptIntent(val id:String,val kind:String,val identity:MigrationIdentity,val schema:String,val body:String,val message:String="",val content:String="",val digest:String="",val proof:String="",val descriptor:String="",val expires:String="",val state:String="pending",val attempts:Int=0,val result:String="") {
    fun json()=JSONObject().put("id",id).put("kind",kind).put("identity",MigrationStore.identityJSON(identity)).put("schema",schema).put("body",body).put("message",message).put("content",content).put("digest",digest).put("proof",proof).put("descriptor",descriptor).put("expires",expires).put("state",state).put("attempts",attempts).put("result",result)
    override fun toString()="ReceiptIntent(redacted)"
}
object ReceiptProtocol {
    fun canonical(value:Any?):String=when(value){null,JSONObject.NULL->"null";is JSONObject->value.keys().asSequence().toList().sorted().joinToString(",","{","}"){JSONObject.quote(it)+":"+canonical(value.get(it))};is org.json.JSONArray->(0 until value.length()).joinToString(",","[","]"){canonical(value.get(it))};is String->JSONObject.quote(value);is Boolean->value.toString();else->error("RECEIPT_INVALID_CANONICAL")}
    const val protocol="qualified-receipts-v1"
    const val contentContract="native_sqlite_full_v1"
    const val objectContract="native_sqlite_full_file_fsync_v1"
    fun pair(p:JSONObject):Pair<String,String>{val generation=p.optString("deliveryGeneration");val digest=p.optString("manifestDigest");require((generation.isEmpty()&&digest.isEmpty())||(MigrationProtocol.positive(generation).isNotEmpty()&&MigrationProtocol.digest(digest).isNotEmpty()));return generation to digest}
    fun proof(token:String,prefix:String,i:MigrationIdentity,qualification:String,permission:String=""):JSONObject {
        require(token.length<=8192);val parts=token.split('.');require(parts.size==3&&parts[0]==prefix&&MigrationProtocol.decode(parts[2],32,true).size==32)
        val p=JSONObject(MigrationProtocol.utf8(MigrationProtocol.decode(parts[1],8192,true)));MigrationProtocol.exact(p,setOf("scope","user","device","store","epoch","qualification","message","conversation","contentVersion","bodyDigest","permission","expires","deliveryGeneration","manifestDigest","parentReceiptId","objectId","sizeBytes","objectDigest"))
        require(p.opt("scope")==i.deployment&&p.opt("user")==i.user&&p.opt("device")==i.device&&p.opt("store")==i.store&&p.opt("epoch")==i.epoch&&p.opt("qualification")==qualification)
        for(k in listOf("message","conversation","qualification"))SyncWire.id(p.opt(k));MigrationProtocol.positive(p.opt("contentVersion"));MigrationProtocol.digest(p.opt("bodyDigest"));require(p.getString("permission").isNotEmpty()&&(permission.isEmpty()||p.opt("permission")==permission));pair(p);require(p.getLong("expires")>0);if(prefix=="ro1"){SyncWire.id(p.opt("objectId"));val parent=p.getString("parentReceiptId");require(parent.toByteArray().size in 8..128&&parent.trim()==parent&&!parent.contains(Regex("[\\r\\n\\u0000]")));require(SyncWire.counter(p.opt("sizeBytes")).toLong()<=64L*1024*1024);MigrationProtocol.digest(p.opt("objectDigest"))};return p
    }
    fun context(raw:JSONObject,i:MigrationIdentity,schema:String):JSONObject {
        require(raw.opt("protocol")==protocol&&raw.opt("scopeId")==i.deployment&&raw.opt("principalId")==i.user&&raw.opt("deviceId")==i.device&&raw.opt("sourceContextId")=="personal"&&raw.opt("storeGeneration")==i.store&&raw.opt("restoreEpoch")==i.epoch&&raw.opt("schemaVersion")==schema&&raw.opt("deletionEligible")==false&&raw.opt("targetRangeComplete")==false&&raw.opt("defaultRetentionMode")=="cloud_history")
        val q=raw.getJSONObject("storage");require(q.opt("storeGeneration")==i.store&&q.opt("restoreEpoch")==i.epoch);val content=q.getBoolean("qualified");val objects=q.getBoolean("objectQualified");require(!objects||content&&q.opt("storageContract")==objectContract);require(raw.opt("qualifiedAck")==content&&raw.opt("contentReceiptEnabled")==content&&raw.opt("objectReceiptEnabled")==objects)
        val ready=raw.getJSONObject("readiness").getBoolean("ready");require(raw.opt("afterReceiptEnabled")== (content&&ready)&&raw.opt("afterObjectReceiptEnabled")== (objects&&ready));require(raw.opt("qualification")==if(objects)"qualified_content_and_objects" else if(content)"qualified_content" else "transport_only")
        if(content){SyncWire.id(q.opt("qualificationId"));MigrationProtocol.digest(q.opt("buildDigest"));MigrationProtocol.digest(q.opt("verificationDigest"));require(q.optString("storageContract") in setOf(contentContract,objectContract))};return raw
    }
    fun measurementIdentity(i:MigrationIdentity):JSONObject=JSONObject().put("profile",i.profile).put("deployment",i.deployment).put("user",i.user).put("device",i.device).put("epoch",i.epoch).put("namespace",i.namespace).put("store",i.store)
    fun localMeasurement(raw:JSONObject,i:MigrationIdentity,build:String):JSONObject {
        MigrationProtocol.exact(raw,setOf("protocol","identity","buildDigest","storageContract","writerFull","reopenBody","reopenIntent","objectFsync","directoryFsync","verificationDigest"));require(raw.opt("protocol")==protocol&&measurementIdentity(i).let{SyncWire.same(it,raw.getJSONObject("identity"))}&&raw.opt("buildDigest")==build&&raw.opt("writerFull")==true&&raw.opt("reopenBody")==true&&raw.opt("reopenIntent")==true)
        val contract=raw.getString("storageContract");require(contract in setOf(contentContract,objectContract));if(contract==objectContract)require(raw.opt("objectFsync")==true&&raw.opt("directoryFsync")==true);val copy=JSONObject(raw.toString());copy.remove("verificationDigest");require(MigrationProtocol.hash(canonical(copy).toByteArray())==raw.opt("verificationDigest"));return raw
    }
    fun parse(raw:JSONObject):ReceiptIntent {
        MigrationProtocol.exact(raw,setOf("id","kind","identity","schema","body","message","content","digest","proof","descriptor","expires","state","attempts","result"));val row=ReceiptIntent(SyncWire.id(raw.opt("id")),raw.getString("kind"),MigrationStore.identity(raw.getJSONObject("identity")),raw.getString("schema"),raw.getString("body"),raw.getString("message"),raw.getString("content"),raw.getString("digest"),raw.getString("proof"),raw.getString("descriptor"),raw.getString("expires"),raw.getString("state"),raw.getInt("attempts"),raw.getString("result"));require(row.kind in setOf("storage","message_content","object_received")&&row.schema in setOf("1","2")&&row.state in setOf("pending","unknown","recorded","retired")&&row.attempts>=0)
        if(row.state=="retired"){require(row.body.isEmpty()&&row.proof.isEmpty()&&row.descriptor.isEmpty());return row}
        val b=JSONObject(row.body);require(b.opt("requestId")==row.id&&b.opt("storeGeneration")==row.identity.store&&b.opt("revisionEpoch")==row.identity.epoch)
        if(row.kind=="storage"){MigrationProtocol.exact(b,setOf("requestId","storeGeneration","revisionEpoch","profileId","buildDigest","verificationDigest"));require(b.getString("profileId").matches(Regex("[A-Za-z0-9_.-]{1,128}")));MigrationProtocol.digest(b.opt("buildDigest"));MigrationProtocol.digest(b.opt("verificationDigest"))}
        else {val allowed=if(row.kind=="message_content")setOf("requestId","storeGeneration","revisionEpoch","qualificationId","kind","challenge","bodyDigest") else setOf("requestId","storeGeneration","revisionEpoch","qualificationId","kind","parentReceiptId","challenge","objectId","sizeBytes","objectDigest");MigrationProtocol.exact(b,allowed);require(b.opt("kind")==row.kind);SyncWire.id(row.message);MigrationProtocol.positive(row.content);MigrationProtocol.digest(row.digest);val p=proof(b.getString("challenge"),if(row.kind=="message_content")"rc1" else "ro1",row.identity,b.getString("qualificationId"));require(SyncWire.same(p,JSONObject(row.proof))&&p.opt("message")==row.message&&p.opt("contentVersion")==row.content&&p.opt("bodyDigest")==row.digest&&Instant.parse(row.expires).epochSecond==p.getLong("expires"));if(row.kind=="message_content")require(b.opt("bodyDigest")==row.digest) else {require(b.opt("parentReceiptId")==p.opt("parentReceiptId")&&b.opt("objectId")==p.opt("objectId")&&b.opt("objectDigest")==p.opt("objectDigest")&&b.opt("sizeBytes")==p.opt("sizeBytes"));val d=JSONObject(row.descriptor);MigrationProtocol.exact(d,setOf("id","path","sha256","sizeBytes","contentType"));require(d.opt("id")==b.opt("objectId")&&d.opt("sha256")==b.opt("objectDigest")&&d.opt("sizeBytes")==b.opt("sizeBytes"));require(d.getString("path").matches(Regex("[0-9a-f-]{36}\\.bin")))}
        };return row
    }
    fun result(raw:JSONObject,row:ReceiptIntent):JSONObject {
        require(row.state!="retired");val b=JSONObject(row.body)
        if(row.kind=="storage"){val r=raw.getJSONObject("result");for(k in listOf("storeGeneration","profileId","buildDigest","verificationDigest"))require(r.opt(k)==b.opt(k));require(r.opt("restoreEpoch")==row.identity.epoch&&raw.opt("deletionEligible")==false&&raw.opt("afterReceiptEnabled")==false&&raw.opt("current") is Boolean);SyncWire.id(r.opt("qualificationId"));return raw}
        val p=JSONObject(row.proof);require(raw.opt("operationId")==row.id&&raw.opt("status")=="recorded"&&raw.opt("receiptKind")==row.kind&&raw.opt("messageId")==row.message&&raw.opt("conversationId")==p.opt("conversation")&&raw.opt("contentVersion")==row.content&&raw.opt("restoreEpoch")==row.identity.epoch&&raw.opt("deviceId")==row.identity.device&&raw.opt("storeGeneration")==row.identity.store&&raw.opt("qualificationId")==b.opt("qualificationId")&&raw.opt("bodyDigest")==row.digest&&raw.opt("storageQualifiedAtCommit")==true&&raw.opt("deletionEligible")==false&&raw.opt("targetRangeComplete")==false&&raw.opt("objectComplete")== (row.kind=="object_received")&&pair(raw)==pair(p))
        if(row.kind=="object_received")for(k in listOf("parentReceiptId","objectId","sizeBytes","objectDigest"))require(raw.opt(k)==b.opt(k));return raw
    }
    fun target(raw:JSONObject,row:ReceiptIntent):JSONObject {val p=JSONObject(row.proof);require(raw.opt("protocol")==protocol&&raw.opt("qualificationId")==JSONObject(row.body).opt("qualificationId")&&raw.opt("messageId")==row.message&&raw.opt("contentVersion")==row.content&&raw.opt("restoreEpoch")==row.identity.epoch&&pair(raw)==pair(p)&&raw.opt("deletionEligible")==false);for(k in listOf("originalTarget","contentTarget","objectTarget","contentRecorded","objectRecorded","current","messageCurrent"))require(raw.opt(k) is Boolean);for(k in listOf("contentCompleteAt","objectCompleteAt"))if(!raw.isNull(k))Instant.parse(raw.getString(k));return raw}
}
